from PIL import Image
import numpy as np
im = Image.open("chess_puzzle.png").convert("RGB")
arr = np.array(im).astype(int)
bg_l=np.array([240,217,181]); bg_d=np.array([181,136,99])

def fg(sq):
    flat=sq.reshape(-1,3).astype(int)
    d=np.minimum(np.abs(flat-bg_l).sum(1),np.abs(flat-bg_d).sum(1)).reshape(80,80)
