for col in ['B','W']:
    items=[o for o in occ if o[2]==col]
    clusters=[]
    for it in items:
        best=None;bd=1e9
        for ci,cl in enumerate(clusters):
            dist=(cl[0][3]!=it[3]).sum()
            if dist<bd: bd=dist;best=ci
        if best is not None and bd<200:
            clusters[best].append(it)
        else:
            clusters.append([it])
    print(f"=== {col}: {len(clusters)} clusters ===")
    for cl in clusters:
        mem=[(o[0],o[1]) for o in cl]
        rep=cl[0]
        print(f"  rep({rep[0]},{rep[1]}) cnt={len(cl)} pix={rep[4]} HxW={rep[5]}x{rep[6]} mem={mem}")
EOF
